import random

class MinesweeperGame:
    MAGIC_X = 'X'
    MAGIC_UNREVEALED = '-'
    INCREMENT_VALUE = 1
    WIN_CONDITION = True
    LOSE_CONDITION = False
    NO_WIN = False

    def __init__(self, n, k) -> None:
        self.n = n
        self.k = k
        self.minesweeper_map = self._generate_mine_sweeper_map()
        self.player_map = self._generate_player_map()
        self.score = 0

    def _generate_mine_sweeper_map(self):
        arr = [[0 for _ in range(self.n)] for _ in range(self.n)]
        for _ in range(self.k):
            x = random.randint(0, self.n - 1)
            y = random.randint(0, self.n - 1)
            arr[y][x] = self.MAGIC_X
            self._increment_neighbors(arr, x, y)
        return arr

    def _increment_neighbors(self, arr, x, y):
        directions = [
            (0, 1), (1, 0), (-1, -1),
            (-1, 1), (0, -1),
            (1, 1), (-1, 1), (0, 1)
        ]
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < self.n and 0 <= ny < self.n:
                if arr[ny][nx] != self.MAGIC_X:
                    arr[ny][nx] += self._get_increment_value()

    def _get_increment_value(self):
        return self.INCREMENT_VALUE

    def _generate_player_map(self):
        return [[self.MAGIC_UNREVEALED for _ in range(self.n)] for _ in range(self.n)]

    def check_won(self):
        for i in range(self.n):
            for j in range(self.n):
                if self.player_map[i][j] == self.MAGIC_UNREVEALED and self.minesweeper_map[i][j] != self.MAGIC_X:
                    return self.LOSE_CONDITION
        return self.WIN_CONDITION

    def sweep(self, x, y):
        if not self._is_valid_sweep(x, y):
            return self.LOSE_CONDITION

        self._reveal_cell(x, y)

        if self._has_won():
            return self.WIN_CONDITION

        return self.player_map

    def _is_valid_sweep(self, x, y):
        return self.minesweeper_map[x][y] != self.MAGIC_X

    def _reveal_cell(self, x, y):
        self.player_map[x][y] = self.minesweeper_map[x][y]
        self._increment_score()

    def _increment_score(self):
        self.score += self.INCREMENT_VALUE

    def _has_won(self):
        return self.check_won()
